  it(
    "nested_newline_only_spans_keep_separator: A newline inside two nested spans still separates the words on either side"
  ) do
    result = HtmlToMarkdown.convert("<p>Alpha<span><span>\n</span></span>Beta</p>")
    expect(result.content.to_s).to(eq("Alpha Beta\n"))
