    result = HtmlToMarkdown.convert("<p>H<sub>2</sub>O and E=mc<sup>2</sup></p>")
    expect(result.content.respond_to?(:empty?) ? !result.content.empty? : !result.content.nil?).to(be(true))
    expect(result.content.to_s).to(include("H"))
    expect(result.content.to_s).to(include("2"))
    expect(result.content.to_s).to(include("O"))
    expect(result.content.to_s).to(include("E=mc"))
