  it(
    "space_only_italic_inside_empty_strong_keeps_separator: A space-only italic nested inside an otherwise empty strong wrapper still separates the words on either side"
  ) do
    result = HtmlToMarkdown.convert("<p><strong>Alpha</strong><strong><i> </i></strong>Beta</p>")
