    result = HtmlToMarkdown.convert("<table></table>")
    expect(result.content.to_s).to(eq(""))
  end

  it(
    "table_layout_cell_paragraphs_stay_separated: Adjacent paragraphs in a layout-table cell are separated rather than concatenated into one run of text"
  ) do
    result = HtmlToMarkdown.convert(
      "<table><tr><td><p><b>Alice Example</b></p><p><i>Customer Service</i></p></td><td>Logo</td></tr><tr><td>A</td><td>B</td><td>C</td></tr></table>",
      HtmlToMarkdown::ConversionOptions.new(compact_tables: true)
    )
    expect(result.content.to_s).not_to(include("**Alice Example***Customer Service*"))
    expect(result.content.to_s).to(include("Alice Example"))
    expect(result.content.to_s).to(include("Customer Service"))
    expect(result.content.to_s).to(include("Logo"))
  end

  it "table_layout_row_keeps_image: A layout-table row keeps an image as Markdown instead of degrading it to alt text" do
    result = HtmlToMarkdown.convert(
      "<table><tr><td><img src=\"a.svg\" alt=\"A\"> <a href=\"/1\">x</a></td><td><a href=\"/2\">y</a></td></tr><tr><td><a href=\"/3\">z</a></td></tr></table>"
    )
    expect(result.content.to_s).to(eq("- ![A](a.svg) [x](/1) [y](/2)\n- [z](/3)\n"))
  end

  it(
    "table_nested_chain_not_misclassified_as_layout: A straight chain of one-nested-table-per-cell tables renders as pipe tables, not a broken layout list"
  ) do
    result = HtmlToMarkdown.convert(
      "<table><tr><td><table><tr><td><table><tr><td>leaf</td></tr></table></td></tr></table></td></tr></table>"
