      "<table><tr><th>Summary</th></tr><tr><td>Before<table><tr><th>Item</th><th>Amount</th></tr><tr><td>Alpha</td><td>10</td></tr></table></td></tr></table>"
    )
    expect(result.content.to_s).to(include("| Item  | Amount |"))
    expect(result.content.to_s).to(include("| Alpha | 10     |"))
    expect(result.content.to_s).not_to(include("\\|"))
  end

  it(
    "table_nested_in_wrapper_renders_separately: A nested table wrapped in a div still renders as its own table rather than raw pipes"
  ) do
    result = HtmlToMarkdown.convert(
      "<table><tr><th>Summary</th></tr><tr><td>Before<div><table><tr><th>Item</th><th>Amount</th></tr><tr><td>Alpha</td><td>10</td></tr></table></div></td></tr></table>"
    )
    expect(result.content.to_s).to(include("| Item  | Amount |"))
    expect(result.content.to_s).to(include("| Alpha | 10     |"))
    expect(result.content.to_s).to(include("Before"))
    expect(result.content.to_s).not_to(include("\\|"))
  end

