  it(
    "table_ragged_row_fewer_cells_than_header: A data row with fewer cells than the header is padded to the declared column count"
  ) do
    result = HtmlToMarkdown.convert(
      "<table><tr><th>A</th><th>B</th><th>C</th></tr><tr><td>1</td><td>2</td></tr></table>"
