  end

  it(
    "table_ragged_rows_padded_not_listed: A headerless table whose rows have different cell counts is padded, not turned into a list"
  ) do
    result = HtmlToMarkdown.convert("<table><tr><td>A</td><td>B</td></tr><tr><td>C</td></tr></table>")
    expect(result.content.to_s).to(eq("| A | B |\n| --- | --- |\n| C |   |\n"))
  end

