    expect(result.content.to_s).to(include("L"))
    expect(result.content.to_s).to(include("C"))
    expect(result.content.to_s).to(include("R"))
    expect(result.content.to_s).to(include("|"))
  end

  it "table_with_colspan: Table with colspan attribute in a header cell" do
    result = HtmlToMarkdown.convert(
