  it "tagged_space_not_duplicated: A whitespace-only inline element contributes exactly one space" do
    result = HtmlToMarkdown.convert("<p>A<i> </i>B</p>")
    expect(result.content.to_s).to(eq("A B\n"))
  end

  it "unordered_list: Unordered list" do
    result = HtmlToMarkdown.convert("<ul><li>Item 1</li><li>Item 2</li><li>Item 3</li></ul>")
    expect(result.content.to_s).to(include("- Item 1"))
    expect(result.content.to_s).to(include("- Item 2"))
    expect(result.content.to_s).to(include("- Item 3"))
  end

  it(
    "whitespace_only_bold_wrapper_keeps_separator: A bold wrapper holding only a newline-only span still separates the words on either side"
  ) do
    result = HtmlToMarkdown.convert("<b>Alpha</b><b><span>\n</span></b><b>Beta</b>")
